            "query": "const addNewRow_synch = async () => {\n  var currentData = [];\n\n  await getCurrentDataFieldsData.trigger({\n    onSuccess: function (data) {\n      currentData = data;\n    },\n  });\n  \n  await addRow(currentData, fieldSelection.value);\n  await createChartData.trigger();\n};\n\naddNewRow_synch();\n\nfunction addRow(currentData, fieldSelection) {\n  currentData.fields.push({\n    field: fieldSelection,\n    chartType: selectChartType.value,\n    aggregate: \"\",\n    marker: selectChartType.value == \"scatter\" ? \"markers\" : \"lines+markers\",\n    color: \"#6975daff\",\n  });\n\n  var currentDataSize = Object.keys(currentData.fields).length;\n\n  tempDataFields.setValue(currentData);\n  tempDataFieldsNumRows.setValue(currentDataSize);\n}\n",
